app.post('/admin/products/:id/variants/:variantId/gallery',auth,upload.array('images',4),async(q,s)=>{let added=[];try{const p=await Product.findOne({legacyId:q.params.id});if(!p)return s.status(404).json({message:'Product not found'});const v=p.getVariant(q.params.variantId);if(!v)return s.status(404).json({message:'Variation not found'});added=await imageLife.uploadAll(q.files||[],p.legacyId,[p.name,v.color,v.size].filter(Boolean).join(' - '));const offset=(v.images||[]).length;v.images.push(...added.map((x,i)=>({...x,primary:false,sortOrder:offset+i})));await p.save();s.json({message:'Gallery images added',images:v.images})}catch(e){await storage.removeMany(added);s.status(400).json({message:e.message})}});
app.patch('/admin/products/:id/variants/:variantId/images/:imageId/alt',auth,async(q,s)=>{try{const p=await Product.findOne({legacyId:q.params.id});if(!p)return s.status(404).json({message:'Product not found'});const v=p.getVariant(q.params.variantId);if(!v)return s.status(404).json({message:'Variation not found'});const img=q.params.imageId==='primary'?(v.images||[]).find(x=>x.primary)||(v.images||[])[0]:(v.images||[]).find(x=>String(x._id)===String(q.params.imageId));if(!img)return s.status(404).json({message:'Image not found'});img.alt=String(q.body.alt||'').trim().slice(0,300);await p.save();s.json({message:'Alt text saved'})}catch(e){s.status(400).json({message:e.message})}});
app.delete('/admin/products/:id/variants/:variantId/gallery/:imageId',auth,async(q,s)=>{try{const p=await Product.findOne({legacyId:q.params.id});if(!p)return s.status(404).json({message:'Product not found'});const v=p.getVariant(q.params.variantId);if(!v)return s.status(404).json({message:'Variation not found'});const index=(v.images||[]).findIndex(x=>String(x._id)===String(q.params.imageId));if(index<0)return s.status(404).json({message:'Image not found'});if(v.images[index].primary)return s.status(400).json({message:'Primary image cannot be deleted'});const old=v.images[index].toObject?v.images[index].toObject():v.images[index];v.images.splice(index,1);await p.save();await storage.removeMany([old]);s.json({message:'Gallery image deleted'})}catch(e){s.status(400).json({message:e.message})}});

app.get('/health',(q,s)=>s.json({ok:mongoose.connection.readyState===1,database:mongoose.connection.readyState===1?'connected':'disconnected',storage:getSupabase()?'configured':'not_configured'}));
