app.get('/product/:slug',async(q,s,n)=>{try{const product=await publicProduct(q.params.slug);if(!product)return s.status(404).sendFile(path.join(ROOT,'public/product.html'));const html=renderProductFile(path.join(ROOT,'public/product.html'),{product:compat.product(product),cfg:seoConfig.current(),req:q});s.type('html').send(html)}catch(e){n(e)}});
