app.use((e,q,s,n)=>{const requestId=crypto.randomUUID();console.error('Request error',requestId,e);if(s.headersSent)return n(e);const status=Number(e.status||e.statusCode)||500;s.status(status>=400&&status<600?status:500).json({message:status>=500?'An internal error occurred. Please contact support with the reference ID.':String(e.message||'Request failed'),requestId,...(process.env.NODE_ENV!=='production'?{stack:e.stack}:{})})});
