let server;async function start(){validateEnv();await connectDB();await require('./services/checkoutReservationService').releaseLegacyDeliveryHolds();require('./services/paymentRecoveryService').start();server=app.listen(PORT,()=>console.log(`${seoConfig.current().siteName} running on port ${PORT}`))}async function stop(){require('./services/paymentRecoveryService').stop();if(server)await new Promise(r=>server.close(r));await closeDB()}process.on('SIGTERM',()=>stop().finally(()=>process.exit(0)));process.on('SIGINT',()=>stop().finally(()=>process.exit(0)));if(require.main===module)start().catch(e=>{console.error(e.message);process.exit(1)});module.exports={app,start,stop,requested,couponDiscount,finalize,resolveRedesignFile};